parameters.jsCode:
const base64 =
  $json.base64 ??
  $json.message?.base64 ??
  '';

if (!base64) {
  throw new Error('Evolution API não retornou base64 do áudio.');
}

const mimeType =
  $json.mimetype ??
  $json.mimeType ??
  'audio/ogg';

let extension='ogg';
if (mimeType.includes('mpeg')) extension='mp3';
else if (mimeType.includes('mp4')) extension='m4a';
else if (mimeType.includes('wav')) extension='wav';
else if (mimeType.includes('webm')) extension='webm';

return [{
  json: {
    media_type: $json.mediaType ?? 'audio',
    mime_type: mimeType
  },
  binary: {
    data: {
      data: base64,
      mimeType,
      fileName: `audio.${extension}`
    }
  }
}];

const original = $('Normalizar Entrada').item.json;

const transcription =
  $json.text ??
  $json.transcript ??
  '';

if (!String(transcription).trim()) {
  throw new Error('A transcrição do áudio veio vazia.');
}

return [{
  json: {
    ...original,
    message: String(transcription).trim(),
    message_type: 'audio',
    transcription: String(transcription).trim()
  }
}];
